<?php

namespace App\WebSockets\Storage\Clients;

use Ratchet\ConnectionInterface;

class AuthorizedClientsStorage implements ClientsStorageInterface
{
    private array $clients = [];

    public function add(ConnectionInterface $conn, int $userId): void
    {
        $this->clients[$conn->resourceId] = [
            'connection' => $conn,
            'userId' => $userId,
        ];
    }

    public function getUserId(ConnectionInterface $conn): ?int
    {
        return $this->clients[$conn->resourceId]['userId'] ?? null;
    }

    public function getConnectionByUserId(int $userId): ?ConnectionInterface
    {
        foreach ($this->clients as $client) {
            if ($client['userId'] === $userId) {
                return $client['connection'];
            }
        }

        return null;
    }

    public function remove(ConnectionInterface $conn): void
    {
        unset($this->clients[$conn->resourceId]);
    }
}
