    {
        return $this->clients[$conn->resourceId]['userData'] ?? null;
    }

    public function getConnectionByUserId(int $userId): ?ConnectionInterface
    {
        foreach ($this->clients as $client) {
            if ($client['userData']->id === $userId) {
                return $client['connection'];
            }
        }

        return null;
    }

