public function allQueues(): array
{
    $pattern = self::QUEUE_PREFIX . '*';
    $keys = Redis::keys($pattern);

    $result = [];
    foreach ($keys as $queueKey) {
        $userIds = Redis::zrange($queueKey, 0, -1);
        foreach ($userIds as $userId) {
            $raw = json_decode(Redis::get($this->getUserDataKey($userId)), true);
            if ($raw !== null) {
                $result[] = [
                    'userId' => $raw['userId'],
                    'name' => $raw['name'],
                    'email' => $raw['email'],
                    'avatar' => $raw['avatar'],
                    'matchParams' => $raw['matchParams'],
                ];
            }
        }
    }

    return $result;
}

public function findMatch(int $userId, array $matchParams): ?int

protected function broadcastQueueUpdated(): void
{
    $queue = $this->matchMakingQueue->allQueues();

    foreach ($this->subscriptionsStorage->getConnectionsByChannel('matchmaking.queue') as $conn) {
        $conn->send(new MatchMakingQueueUpdatedMessage($queue));
    }
}

