### 3. **Создание матча с mixed участниками:**

```php
// MatchService.php
public function create(array $data, array $participants): Match
{
    $match = Match::create([
        'dictionary_id' => $data['dictionary_id'],
        'match_type' => $data['match_type'],
        'match_type_params' => $data['match_type_params'],
        'status' => MatchStatus::New,
    ]);

    // $participants = [
    //   ['type' => 'user', 'id' => 123],
    //   ['type' => 'guest', 'id' => 'uuid-guest-1'],
    //   ['type' => 'user', 'id' => 456],
    // ]

    foreach ($participants as $participant) {
        if ($participant['type'] === 'user') {
            $user = User::find($participant['id']);
            MatchUser::fromUser($user, $match->id);
        } else {
            MatchUser::fromGuest(
                $participant['id'], 
                $match->id,
                $participant['name'] ?? null
            );
        }
    }

    event(new MatchCreatedEvent($match));

    return $match;
}
```

