// MatchController.php
public function getActiveMatch(Request $request): ?MatchResource
{
    $userId = $request->user()?->id;
    $guestId = $request->input('guest_id');

    $match = Match::where(function($q) use ($userId, $guestId) {
        $q->whereHas('matchUsers', function($q) use ($userId, $guestId) {
            if ($userId) {
                $q->where('user_id', $userId);
            } elseif ($guestId) {
                $q->where('guest_id', $guestId);
            }
        });
    })
    ->where('status', MatchStatus::InProgress)
    ->with(['matchUsers', 'steps'])
    ->first();

    return $match ? new MatchResource($match) : null;
}
